import java.util.concurrent.Executors;
import java.util.concurrent.ThreadFactory;
import java.time.Duration;
import java.util.stream.IntStream;

public class VirtualThreadDemo {
    public static void main(String[] args) throws InterruptedException {
        // Create an Executor that launches a new virtual thread for every task
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            IntStream.range(0, 10_000).forEach(i -> {
                executor.submit(() -> {
                    Thread.sleep(Duration.ofSeconds(1)); // Non-blocking unmounts carrier
                    return i;
                });
            });
        } // executor.close() awaits completion automatically
        System.out.println("All 10,000 tasks completed successfully without thread exhaustion.");
    }
}
